1	import type { LogtoOidcConfigType, OidcPrivateKey } from '@logto/schemas';
2	import { OidcSigningKeyStatus } from '@logto/schemas';
3	
4	import RequestError from '#src/errors/RequestError/index.js';
5	import { createLogtoConfigQueries } from '#src/queries/logto-config.js';
6	import type Queries from '#src/tenants/Queries.js';
7	
8	type NormalizedOidcPrivateKey = OidcPrivateKey & {
9	  status: OidcSigningKeyStatus;
10	};
11	
12	const oidcPrivateKeyStatusOrder: Record<OidcSigningKeyStatus, number> = {
13	  [OidcSigningKeyStatus.Next]: 0,
14	  [OidcSigningKeyStatus.Current]: 1,
15	  [OidcSigningKeyStatus.Previous]: 2,
16	};
17	
18	const oidcProviderPrivateKeyOrder: Record<OidcSigningKeyStatus, number> = {
19	  [OidcSigningKeyStatus.Current]: 0,
20	  [OidcSigningKeyStatus.Next]: 1,
21	  [OidcSigningKeyStatus.Previous]: 2,
22	};
23	
24	const sortOidcPrivateKeys = (
25	  privateKeys: NormalizedOidcPrivateKey[],
26	  order: Record<OidcSigningKeyStatus, number>
27	): NormalizedOidcPrivateKey[] =>
28	  privateKeys.toSorted((left, right) => order[left.status] - order[right.status]);
29	
30	/**
31	 * Normalize private signing keys from legacy index-based lifecycle semantics into explicit statuses.
32	 */
33	export const normalizeOidcPrivateKeys = (
34	  privateKeys: LogtoOidcConfigType['oidc.privateKeys']
35	): NormalizedOidcPrivateKey[] => {
36	  const normalizedPrivateKeys = privateKeys.map((privateKey, index) => ({
37	    ...privateKey,
38	    status:
39	      privateKey.status ??
40	      (index === 0 ? OidcSigningKeyStatus.Current : OidcSigningKeyStatus.Previous),
41	  }));
42	
43	  const currentKeys = normalizedPrivateKeys.filter(
44	    ({ status }) => status === OidcSigningKeyStatus.Current
45	  );
46	  const nextKeys = normalizedPrivateKeys.filter(
47	    ({ status }) => status === OidcSigningKeyStatus.Next
48	  );
49	  const previousKeys = normalizedPrivateKeys.filter(
50	    ({ status }) => status === OidcSigningKeyStatus.Previous
51	  );
52	
53	  if (currentKeys.length !== 1 || nextKeys.length > 1 || previousKeys.length > 1) {
54	    throw new Error(
55	      'Malformed OIDC private key status configuration: expected exactly one Current key and at most one Next and Previous key.'
56	    );
57	  }
58	
59	  return normalizedPrivateKeys;
60	};
61	
62	/**
63	 * Order private signing keys in the canonical business-state order.
64	 */
65	export const getCanonicalOidcPrivateKeys = (
66	  privateKeys: LogtoOidcConfigType['oidc.privateKeys']
67	): OidcPrivateKey[] =>
68	  sortOidcPrivateKeys(normalizeOidcPrivateKeys(privateKeys), oidcPrivateKeyStatusOrder);
69	
70	/**
71	 * Get the effective current signing key from normalized private key state.
72	 */
73	export const getCurrentOidcPrivateKey = (
74	  privateKeys: LogtoOidcConfigType['oidc.privateKeys']
75	): OidcPrivateKey => {
76	  const currentKey = normalizeOidcPrivateKeys(privateKeys).find(
77	    ({ status }) => status === OidcSigningKeyStatus.Current
78	  );
79	
80	  if (!currentKey) {
81	    throw new Error('Malformed OIDC private key status configuration: missing Current key.');
82	  }
83	
84	  return currentKey;
85	};
86	
87	/**
88	 * Order private signing keys the way oidc-provider should consume them.
89	 */
90	export const getOidcProviderPrivateKeys = (
91	  privateKeys: LogtoOidcConfigType['oidc.privateKeys']
92	): OidcPrivateKey[] =>
93	  sortOidcPrivateKeys(normalizeOidcPrivateKeys(privateKeys), oidcProviderPrivateKeyOrder);
94	
95	/**
96	 * Build the persisted private-key state for the current immediate-rotation flow.
97	 */
98	export const getImmediatelyRotatedOidcPrivateKeys = (
99	  privateKeys: LogtoOidcConfigType['oidc.privateKeys'],
100	  newPrivateKey: OidcPrivateKey
101	): OidcPrivateKey[] => {
102	  const currentKey = getCurrentOidcPrivateKey(privateKeys);
103	
104	  return [
105	    { ...newPrivateKey, status: OidcSigningKeyStatus.Current },
106	    { ...currentKey, status: OidcSigningKeyStatus.Previous },
107	  ];
108	};
109	
110	/**
111	 * Rebuild the immediate-flow persisted private-key state after deleting a Previous key.
112	 */
113	export const getOidcPrivateKeysAfterDeletion = (
114	  privateKeys: LogtoOidcConfigType['oidc.privateKeys'],
115	  deletedKeyId: string
116	): OidcPrivateKey[] =>
117	  getCanonicalOidcPrivateKeys(privateKeys).filter(({ id }) => id !== deletedKeyId);
118	
119	export class OidcPrivateKeyLibrary {
120	  constructor(private readonly queries: Queries) {}
121	
122	  async deletePrivateSigningKey(keyId: string): Promise<OidcPrivateKey[]> {
123	    return this.queries.pool.transaction(async (connection) => {
124	      const logtoConfigQueries = createLogtoConfigQueries(connection, this.queries.wellKnownCache);
125	
126	      await logtoConfigQueries.lockPrivateSigningKeys();
127	
128	      const privateKeys = normalizeOidcPrivateKeys(
129	        await logtoConfigQueries.getPrivateSigningKeys()
130	      );
131	
132	      if (privateKeys.length <= 1) {
133	        throw new RequestError({ code: 'oidc.key_required', status: 422 });
134	      }
135	
136	      const deletingKey = privateKeys.find(({ id }) => id === keyId);
137	
138	      if (!deletingKey) {
139	        throw new RequestError({ code: 'oidc.key_not_found', id: keyId, status: 404 });
140	      }
141	
142	      if (deletingKey.status !== OidcSigningKeyStatus.Previous) {
143	        throw new RequestError({
144	          code: 'oidc.only_previous_key_can_be_deleted',
145	          status: 422,
146	        });
147	      }
148	
149	      const updatedPrivateKeys = getOidcPrivateKeysAfterDeletion(privateKeys, keyId);
150	      await logtoConfigQueries.upsertPrivateSigningKeys(updatedPrivateKeys);
151	
152	      return updatedPrivateKeys;
153	    });
154	  }
155	
156	  async rotatePrivateSigningKeys(newPrivateKey: OidcPrivateKey): Promise<OidcPrivateKey[]> {
157	    return this.queries.pool.transaction(async (connection) => {
158	      const logtoConfigQueries = createLogtoConfigQueries(connection, this.queries.wellKnownCache);
159	
160	      await logtoConfigQueries.lockPrivateSigningKeys();
161	
162	      const privateKeys = normalizeOidcPrivateKeys(
163	        await logtoConfigQueries.getPrivateSigningKeys()
164	      );
165	
166	      if (privateKeys.some(({ status }) => status === OidcSigningKeyStatus.Next)) {
167	        throw new RequestError({ code: 'oidc.invalid_request', status: 422 });
168	      }
169	
170	      const updatedPrivateKeys = getImmediatelyRotatedOidcPrivateKeys(privateKeys, newPrivateKey);
171	      await logtoConfigQueries.upsertPrivateSigningKeys(updatedPrivateKeys);
172	
173	      return updatedPrivateKeys;
174	    });
175	  }
176	}
