154	          }
155	
156	          const value = await run.apply(this, args);
157	
158	          await trySafe(kvCache.set(type, promiseKey, value, getExpiresIn?.(value)));
159	
160	          return value;
161	        } finally {
162	          promiseCache.delete(promiseKey);
163	        }
164	      })();
165	
166	      promiseCache.set(promiseKey, promise);
167	
168	      return promise;
169	    };
170	
171	    return memoized;
172	  }
